-- 特定目的载体持有信息（投资者）接口表 新增
DROP TABLE PBC_TARGET_INFO;
CREATE TABLE
 PBC_TARGET_INFO(
  UUID varchar(36)   NULL ,
  ACCOUNT varchar(50)   not NULL ,
  INDENTIFY_MARK varchar(30)  NOT NULL ,
  PBC_PROD_ID varchar(100)    NULL ,
  HOLDER_NAME varchar(200)   DEFAULT NULL ,
  HOLDER_TYPE varchar(2)   DEFAULT NULL ,
  HOLD_DATE date   DEFAULT NULL ,
  CCY varchar(10)  DEFAULT NULL ,
  QTY DECIMAL(32,5)  DEFAULT NULL ,
  AMOUNT DECIMAL(32,2)   DEFAULT NULL ,
  CREATE_TIME DATE   DEFAULT NULL ,
  UPDATE_TIME DATE   DEFAULT NULL ,
  CREATE_USER varchar(50)  DEFAULT NULL ,
  CREATE_DEPT varchar(10)  DEFAULT NULL ,
  UPDATE_USER varchar(10)  DEFAULT NULL ,
  STATUS varchar(50)  DEFAULT NULL ,
        CONSTRAINT PBC_TARGET_INFO_PK PRIMARY KEY (UUID)
    );
COMMENT ON TABLE PBC_TARGET_INFO IS '特定目的载体持有信息（投资者）接口表';
COMMENT ON COLUMN PBC_TARGET_INFO.UUID IS 'UUID';
COMMENT ON COLUMN PBC_TARGET_INFO.ACCOUNT IS '产品代码';
COMMENT ON COLUMN PBC_TARGET_INFO.INDENTIFY_MARK IS '识别标识';
COMMENT ON COLUMN PBC_TARGET_INFO.PBC_PROD_ID IS '人行产品代码';
COMMENT ON COLUMN PBC_TARGET_INFO.HOLDER_NAME IS '投资者名称';
COMMENT ON COLUMN PBC_TARGET_INFO.HOLDER_TYPE IS '投资者类别';
COMMENT ON COLUMN PBC_TARGET_INFO.HOLD_DATE IS '持有日期';
COMMENT ON COLUMN PBC_TARGET_INFO.CCY IS '币种';
COMMENT ON COLUMN PBC_TARGET_INFO.QTY IS '持有份额';
COMMENT ON COLUMN PBC_TARGET_INFO.AMOUNT IS '持有金额';
COMMENT ON COLUMN PBC_TARGET_INFO.CREATE_TIME IS '创建日期';
COMMENT ON COLUMN PBC_TARGET_INFO.UPDATE_TIME IS '更新日期';
COMMENT ON COLUMN PBC_TARGET_INFO.CREATE_USER IS '创建人';
COMMENT ON COLUMN PBC_TARGET_INFO.CREATE_DEPT IS '创建人';
COMMENT ON COLUMN PBC_TARGET_INFO.UPDATE_USER IS '创建部门';
COMMENT ON COLUMN PBC_TARGET_INFO.STATUS IS '数据状态';


DROP TABLE PBC_TARGET_INFO_ERRORDATA;
CREATE TABLE
 PBC_TARGET_INFO_ERRORDATA(
  UUID varchar(36)   NULL ,
  ACCOUNT varchar(50)   not NULL ,
  INDENTIFY_MARK varchar(30)  NOT NULL ,
  PBC_PROD_ID varchar(100)    NULL ,
  HOLDER_NAME varchar(200)   DEFAULT NULL ,
  HOLDER_TYPE varchar(2)   DEFAULT NULL ,
  HOLD_DATE date   DEFAULT NULL ,
  CCY varchar(10)  DEFAULT NULL ,
  QTY DECIMAL(32,5)  DEFAULT NULL ,
  AMOUNT DECIMAL(32,2)   DEFAULT NULL ,
  CREATE_TIME DATE   DEFAULT NULL ,
  UPDATE_TIME DATE   DEFAULT NULL ,
  CREATE_USER varchar(50)  DEFAULT NULL ,
  CREATE_DEPT varchar(10)  DEFAULT NULL ,
  UPDATE_USER varchar(10)  DEFAULT NULL ,
  STATUS varchar(50)  DEFAULT NULL ,
  ERR_MSG  CLOB,
  ORG_DATA  CLOB,
        CONSTRAINT PBC_T_ERROR_PK PRIMARY KEY (UUID)
    );
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.UUID IS 'UUID';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.ACCOUNT IS '产品代码';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.INDENTIFY_MARK IS '识别标识';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.PBC_PROD_ID IS '人行产品代码';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.HOLDER_NAME IS '投资者名称';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.HOLDER_TYPE IS '投资者类别';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.HOLD_DATE IS '持有日期';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.CCY IS '币种';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.QTY IS '持有份额';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.AMOUNT IS '持有金额';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.CREATE_TIME IS '创建日期';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.UPDATE_TIME IS '更新日期';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.CREATE_USER IS '创建人';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.CREATE_DEPT IS '创建人';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.UPDATE_USER IS '创建部门';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.STATUS IS '数据状态';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.ERR_MSG IS '错误信息';
COMMENT ON COLUMN PBC_TARGET_INFO_ERRORDATA.ORG_DATA IS '原始数据';


